effect.shader:
const float SQRT3 = 1.7320508;

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    float size = max(cellSize, 2.0) * acEscalaDePixel;
    vec2 metade = acResolution * 0.5;

    float ang = radians(rotation);
    mat2 turn = mat2(cos(ang), -sin(ang), sin(ang), cos(ang));
    vec2 p = turn * (acScreenNorm * acResolution - metade) + metade;

    // Duas grades retangulares simples, uma deslocada meia célula da outra
    // nos dois eixos — a união das duas É uma grade hexagonal.
    vec2 s = vec2(size, size * SQRT3);
    vec2 candidateA = (floor(p / s) + 0.5) * s;
    vec2 q = p - s * 0.5;
    vec2 candidateB = (floor(q / s) + 0.5) * s + s * 0.5;

    float dA = length(p - candidateA);
    float dB = length(p - candidateB);
    vec2 center = dA < dB ? candidateA : candidateB;
    float bestDist = min(dA, dB);
    float secondDist = max(dA, dB);

    // Desgira o centro achado pra amostrar no lugar certo da imagem original.
    mat2 turnBack = mat2(cos(-ang), -sin(-ang), sin(-ang), cos(-ang));
    vec2 centerScreen = turnBack * (center - metade) + metade;
    vec4 hex = texture(inputImg, clamp(centerScreen / acResolution, 0.0, 1.0));

    if (edgeWidth > 0.0) {
        float border = smoothstep(0.0, max(edgeWidth, 0.001) * size, secondDist - bestDist);
        hex.rgb = mix(edgeColor.rgb, hex.rgb, border);
    }

    fragColor = hex;
}
